lessons.solution_code:
class TempValue:
    def __init__(self, obj, attr, value):
        self.obj = obj
        self.attr = attr
        self.value = value
        self._old = None

    def __enter__(self):
        self._old = getattr(self.obj, self.attr)
        setattr(self.obj, self.attr, self.value)
        return self

    def __exit__(self, *args):
        setattr(self.obj, self.attr, self._old)

tests.unittest_code:
def test_temp_value(self):
    class Box:
        def __init__(self):
            self.x = 1
    b = Box()
    with TempValue(b, 'x', 99):
        self.assertEqual(b.x, 99)
    self.assertEqual(b.x, 1)

