lessons.solution_code:
class locked:
    def __init__(self, flag_dict):
        self.flag_dict = flag_dict

    def __enter__(self):
        self.flag_dict['locked'] = True
        return self

    def __exit__(self, *args):
        self.flag_dict['locked'] = False

tests.unittest_code:
def test_locked(self):
    flags = {'locked': False}
    with locked(flags):
        self.assertTrue(flags['locked'])
    self.assertFalse(flags['locked'])
